def ny(key,col,extra=[]):
    ys=[v[1] for v in byk[key]['flow']['nodes'].values() if v[0]==col]+extra
    return max(ys)+84 if ys else 40
add_nodes={};add_edges={};add_meta={}
def add(key,nid,col,sent,label,sub,comps,aliases,desc,why):
    prev=[v[1] for v in add_nodes.get(key,{}).values() if v[0]==col]
    y=ny(key,col,prev)
    add_nodes.setdefault(key,{})[nid]=[col,y,sent,label,sub]
    add_meta.setdefault(key,{})[nid]={"companies":comps,"aliases":aliases,"desc":desc,"why":why}
